const programs = $input.all().map(i => i.json);

if (!programs.length) {
  return [{ json: { skipped: true, reason: 'No active programs found', run_date: new Date().toISOString() } }];
}

// Build per-org digest
const orgs = {};
for (const p of programs) {
  if (!orgs[p.org_id]) {
    orgs[p.org_id] = { org_name: p.org_name, programs: [] };
  }
  const pct = p.total_count > 0 ? Math.round((p.complete_count / p.total_count) * 100) : 0;
  orgs[p.org_id].programs.push({
    program_name: p.name,
    status: p.status,
    current_phase: p.current_phase,
    sprs_score: p.sprs_score,
    far_above_score: p.far_above_score,
    complete_count: parseInt(p.complete_count) || 0,
    total_count: parseInt(p.total_count) || 0,
    completion_pct: pct
  });
}

const totalPrograms = programs.length;
const avgSprs = programs.reduce((sum, p) => sum + (p.sprs_score || 0), 0) / totalPrograms;

const digest = {
  run_date: new Date().toISOString(),
  week: new Date().toISOString().substring(0, 10),
  total_active_programs: totalPrograms,
  average_sprs: Math.round(avgSprs),
  orgs: Object.values(orgs)
};

const description = `Weekly digest: ${totalPrograms} active program(s), avg SPRS ${Math.round(avgSprs)}, generated ${new Date().toISOString().substring(0, 10)}`;

return [{ json: { digest_json: JSON.stringify(digest), description, total_programs: totalPrograms } }];
